import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"RFC-0016: Full Base-OS Updates (A/B Root Filesystem)","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-os/blob/main/docs/rfcs/0016-full-base-os-updates.md"},"headers":[],"relativePath":"sovereign-os/rfcs/0016-full-base-os-updates.md","filePath":"sovereign-os/rfcs/0016-full-base-os-updates.md"}'),r={name:"sovereign-os/rfcs/0016-full-base-os-updates.md"};function s(n,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="rfc-0016-full-base-os-updates-a-b-root-filesystem" tabindex="-1">RFC-0016: Full Base-OS Updates (A/B Root Filesystem) <a class="header-anchor" href="#rfc-0016-full-base-os-updates-a-b-root-filesystem" aria-label="Permalink to &quot;RFC-0016: Full Base-OS Updates (A/B Root Filesystem)&quot;">​</a></h1><p><strong>Status:</strong> Accepted (2026-08-01). <strong>Implementation status (as of 2026-08-06):</strong> the <code>tryboot</code> A/B cycle (stage/trial/verify/commit), signed-manifest release tooling, <code>recover</code>/<code>prune</code> transaction integration, and CI release-candidate wiring are all done and hardware- or live-verified — see the dated progress entries under Testing Strategy for evidence of each, most recently a live CI run (<a href="https://github.com/sovereignfs/sovereign-os/actions/runs/31030670477" target="_blank" rel="noreferrer">31030670477</a>) producing a real, digest-verified base-OS artifact. <strong>Every Acceptance Criteria item is now met</strong>, including the last two that were open as of 2026-08-06 earlier the same day: the qualification device received a second base-OS update without a second reflash, hardware-verified end to end (stage/trial/health-gate/commit, persistent across an ordinary reboot); and the Console base-OS status panel was deployed onto the (separately stale) live Console and confirmed serving real transaction data through the real nginx proxy. See the <a href="./../research/second-base-os-update-hardware-qualification-report.html">second base-OS update qualification report</a> for the full account, including four real defects the pass found — all specific to already-flashed devices carrying pre-fix binaries or baked-in content, none blocking a freshly-flashed device. <strong>All four are now resolved (2026-08-07):</strong> the <code>proof</code>/<code>preview</code> semver-ordering collision and the <code>installed_base_os_version</code> hardcoded-placeholder gap both got real code fixes (<code>compare_versions</code>&#39;s <code>PRERELEASE_CHANNEL_ORDER</code> table; <code>pre-image.sh</code> now templates from <code>$SOVEREIGN_VERSION</code>), each with new test coverage; the other two needed no separate fix, since current <code>main</code> already contained their fixes — the qualification device just hadn&#39;t received them yet, which is precisely how the pass diagnosed both. <strong>The external recovery-image path, RFC-0016&#39;s last named-but-undesigned requirement, is decided and hardware-qualified (2026-08-07/09)</strong> — see <a href="./../adrs/0011-external-recovery-image-path.html">ADR-0011</a> and the <a href="./../research/external-recovery-backup-restore-qualification-report.html">external recovery backup/restore qualification report</a>: a genuine device reflash followed by a genuine restore of a pre-reflash backup, every file independently verified byte-for-byte, zero code changes needed. This milestone&#39;s implementation is now complete; only small implementation-detail questions remain in Unresolved Questions, none of them blocking. <strong>Author:</strong> Project creator and Claude <strong>Created:</strong> 2026-08-01 <strong>Reviewers:</strong><strong>Target phase:</strong> ROADMAP item 6, &quot;Full Base-OS Updates&quot; <strong>Supersedes:</strong> None</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Extend Sovereign&#39;s update system below the &quot;appliance&quot; layer it already covers to the base OS itself — kernel, firmware, Docker, systemd units, and any other content baked into the image at build time — using a redundant (A/B) root-filesystem layout on the Raspberry Pi 5&#39;s own <code>tryboot</code> firmware mechanism, verified and committed by reusing the signed/staged/health-gated/rollback machinery <code>sovereign-update</code> already has, rather than adopting a third-party OTA framework.</p><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p><code>sovereign-update</code>&#39;s existing <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code> sequence (RFC-0014, hardware-qualified across many releases this project has shipped) updates exactly one thing: the versioned &quot;appliance&quot; content under <code>/opt/sovereign/releases/&lt;version&gt;/appliance/</code> — Pi-hole&#39;s pinned container, nginx config, Console binaries, and <code>sovereign-update</code> itself. Everything else on the device — the Debian base, kernel, firmware, Docker Engine, and every systemd unit file under <code>/etc/systemd/system/</code> that ships in the rootfs overlay — is fixed at whatever the device was originally flashed with. There is no path to change any of it short of a full reflash.</p><p>This was a deliberate, explicit deferral (ADR-0002: &quot;Implement A/B root filesystems immediately — Deferred because it adds bootloader, partition, storage, health-commit, and recovery complexity before the POC image is proven&quot;; RFC-0014 lists &quot;A/B root filesystem implementation&quot; as a non-goal), not an oversight. The persistent <code>/data</code> partition was deliberately separated from the start specifically to keep this door open (ADR-0002: &quot;A dedicated data partition prepares the product for A/B OS updates&quot;).</p><p>That deferral has now produced a concrete, repeatedly-felt operational cost, not just a theoretical gap. During ADR-0009&#39;s hardware qualification (Console-triggered install), a device flashed with <code>v0.1.0-preview.18</code> could never exercise the feature under test at all — <code>.18</code>&#39;s rootfs predated ADR-0008/0009&#39;s systemd units entirely, and no amount of appliance-layer updating could install them. The device had to be reflashed with a newer full image before qualification could even start. Every new systemd unit, base-package security fix, or Docker Engine upgrade this project ships from here forward will hit the same wall on every already-deployed device, growing more disruptive the longer it goes unaddressed.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Update the base OS (kernel, firmware, Docker Engine, systemd units, and other rootfs content) on an installed device without reflashing and without losing <code>/data</code>.</li><li>Reuse the existing signed-manifest, staged, health-gated, automatic-rollback model (RFC-0014) rather than building a second, parallel trust/state-machine system for this layer.</li><li>Atomic slot selection with automatic fallback: a base-OS update that fails to boot or fails health checks must return the device to the previously-working slot without operator intervention.</li><li>Keep <code>/data</code> fully independent of either root slot, as already established.</li><li>Preserve the existing appliance-layer updater&#39;s role: base-OS updates and appliance updates remain distinct, independently versioned concerns (<code>components.image_base.version</code> vs. <code>components.appliance.version</code>, already present in every release manifest — see RFC-0014&#39;s release model).</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li>Changing anything about how appliance-layer updates work today. This RFC adds a layer beneath RFC-0014&#39;s mechanism; it does not replace it.</li><li>Fleet orchestration, staged rollout percentages, or any hosted management service. Sovereign does not depend on a vendor&#39;s cloud console for updates (see the image-build assessment&#39;s explicit rejection of Raspberry Pi Connect as a dependency).</li><li>Solving migration for devices that cannot be repartitioned in place (see Compatibility and Migration) beyond documenting the limitation honestly.</li><li>Multi-platform support. This targets Raspberry Pi 5 specifically, the project&#39;s only supported hardware target.</li></ul><h2 id="context-and-evidence" tabindex="-1">Context and Evidence <a class="header-anchor" href="#context-and-evidence" aria-label="Permalink to &quot;Context and Evidence&quot;">​</a></h2><ul><li>ADR-0002 named the data partition&#39;s separation from root as deliberate groundwork for this exact milestone, and named &quot;base-OS security maintenance requires A/B implementation sooner&quot; as an explicit revisit condition. That condition has now been met.</li><li><code>docs/roadmap/01-1-update-foundation.md</code> §13 already sketches the target partition layout (<code>boot / root A / root B / data</code>) and names the three candidate mechanisms to research: RAUC, Mender, and Raspberry Pi&#39;s native <code>tryboot</code>.</li><li><code>docs/research/image-build-system-assessment.md</code> documents that <code>rpi-image-gen</code> — the builder this project already uses — ships an <code>ab_userdata</code> GPT layout example and an official OTA example built on <code>tryboot</code>, explicitly citing them as evidence the builder was chosen partly <em>because</em> it supports this direction. It also explicitly warns that builder&#39;s own OTA example is tied to Raspberry Pi Connect and &quot;does not replace Sovereign&#39;s independent update-system design.&quot;</li><li>The current image layout gives root a fixed, modest footprint (2.5G on the qualification device, not &quot;the whole disk&quot; — see the corrected numbers below), but it is <code>data</code> — not root — that expands to consume every byte of physical media the build-time layout didn&#39;t already claim, via <code>expand-data-partition</code>&#39;s <code>growpart</code> call at first boot (<code>image-builder/sovereign/layer/sovereign-proof.rootfs-overlay/usr/lib/sovereign/expand-data-partition</code>). By the time any device has completed its first boot, <code>data</code> occupies everything after <code>root</code> with no gap remaining. This is the central migration constraint below — not because root itself is oversized, but because nothing is reserved anywhere on the disk for a partition that doesn&#39;t exist yet in the build-time layout.</li><li><code>docs/research/console-triggered-install-qualification-report.md</code> documents the concrete incident that motivates prioritizing this now: a <code>.18</code>-flashed device structurally could not test a feature whose code had shipped weeks earlier, because that feature&#39;s systemd units live in the rootfs, not the appliance layer.</li><li>The partition layout and <code>tryboot_a_b</code> mechanism described in Proposal are read directly from upstream <code>rpi-image-gen</code>&#39;s official <code>image/gpt/ab_userdata</code> example (checked against a local copy of release <code>v2.7.0</code> during this RFC&#39;s research), not secondhand description — specifically its <code>genimage.cfg.in.ext4</code> (partition table), <code>pre-image.sh</code> (the <code>autoboot.txt</code> this project&#39;s design reuses verbatim), and <code>device/rootfs-overlay</code> (confirms no runtime script rewrites <code>autoboot.txt</code>; promotion is firmware-only). This example also includes cryptroot, eMMC write-protect, and erofs variants Sovereign does not need — implementation should extract the relevant ext4/plaintext subset, not adopt the example wholesale, and should vendor or pin the exact upstream commit actually used, per this project&#39;s existing pinning discipline (RFC-0010).</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><h3 id="target-partition-layout" tabindex="-1">Target partition layout <a class="header-anchor" href="#target-partition-layout" aria-label="Permalink to &quot;Target partition layout&quot;">​</a></h3><p>Corrected from the original draft after direct inspection of <code>rpi-image-gen</code>&#39;s own official <code>image/gpt/ab_userdata</code> reference example (vendored locally during this project&#39;s earlier build-system research; this is the same example the image-build assessment cited as evidence for choosing this builder). The real reference layout has more parts than this RFC first assumed, and the mechanism is simpler and more precisely specified than the earlier &quot;shared boot partition with an <code>os_prefix</code> subdirectory&quot; guess:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bootconfig  (new, tiny — GPT partition holding only autoboot.txt, the</span></span>
<span class="line"><span>             tryboot control file the firmware reads before anything else)</span></span>
<span class="line"><span>boot A      (kernel, initramfs, dtbs, config.txt for slot A — whole,</span></span>
<span class="line"><span>             separate FAT partition, not a subdirectory of a shared boot)</span></span>
<span class="line"><span>boot B      (same, for slot B)</span></span>
<span class="line"><span>root A      (ext4, read-only at runtime — see &quot;Root is read-only&quot; below)</span></span>
<span class="line"><span>root B      (same, inactive except during/after an update)</span></span>
<span class="line"><span>data        (unchanged: /data, independent of every other partition,</span></span>
<span class="line"><span>             existing growpart-on-first-boot behavior unaffected —</span></span>
<span class="line"><span>             and now also where /opt/sovereign&#39;s appliance-release tree</span></span>
<span class="line"><span>             lives, moved out of root; see &quot;Root is read-only&quot; below)</span></span></code></pre></div><p>Six partitions instead of today&#39;s three (<code>boot</code>/<code>root</code>/<code>data</code>) — moving to <strong>GPT</strong>, not the MBR partition table this project&#39;s images use today (see Unresolved Questions for why: six partitions don&#39;t fit MBR&#39;s practical 4-primary-partition ceiling without nesting most of them inside an extended partition).</p><p>Root A and root B are each sized to comfortably hold the base OS with headroom for the packages this project actually installs (see <code>image-builder/sovereign/layer/sovereign-proof.yaml</code>&#39;s package list) — not sized to 100% of the disk. <code>data</code> continues to expand to fill whatever remains, as it does today.</p><p>Real numbers from this project&#39;s own qualification device, checked directly (<code>df -h</code>, <code>lsblk -f</code>) rather than assumed:</p><ul><li><strong>root</strong> is currently 2.5G total, 1022M used (44%). A root slot sized around 3G, comfortably covering today&#39;s usage with headroom for growth, is a reasonable starting point for both A and B — a modest ~6G total for both slots against devices this project targets (the qualification device alone has 113G of <code>/data</code>).</li><li><strong>boot</strong> is currently a single 98M partition with only <strong>49M free</strong>. Under the corrected layout above, boot content splits into two <em>separate</em> partitions (boot A, boot B), each holding only one slot&#39;s kernel/initramfs/dtbs at a time — this actually relaxes the original concern (a single ~98–120M partition per slot, not one shared partition needing to hold both simultaneously with near-zero margin). <code>kernel_2712.img</code> (10M) + <code>initramfs_2712</code> (14M) total ~24M today, so each of boot A/boot B needs to be sized comfortably above that, not the current 98M split two ways. Two smaller, real, independent findings either way: the current image ships device trees for boards this project doesn&#39;t support at all (<code>bcm2710-*</code>/<code>bcm2711-*</code>, Pi 2/3/4/CM4 — ~500K combined, out of 20 <code>.dtb</code> files total for a Pi-5-only product) — cheap cleanup worth doing regardless of this RFC&#39;s outcome; and the new tiny <code>bootconfig</code> partition (32M in the reference example) holding only <code>autoboot.txt</code> is new overhead this layout didn&#39;t have before, though trivial in absolute size.</li><li>No <code>autoboot.txt</code> exists on this device today (confirmed directly) — as expected, since nothing has configured <code>tryboot</code> yet. The bootloader itself is well past the version that added <code>tryboot</code> support (this device: EEPROM dated 2025-11-05; <code>tryboot</code> shipped in Raspberry Pi&#39;s 2023-05-11 firmware release), so the firmware prerequisite is already satisfied on hardware this project already qualifies against — the gap is purely in image layout and <code>sovereign-update</code> integration, not firmware readiness.</li></ul><h3 id="root-is-read-only" tabindex="-1">Root is read-only <a class="header-anchor" href="#root-is-read-only" aria-label="Permalink to &quot;Root is read-only&quot;">​</a></h3><p><strong>Decided (2026-08-02, project creator): root A/root B are read-only at runtime</strong>, matching <code>rpi-image-gen</code>&#39;s own reference design rather than keeping root writable as this RFC originally sketched. Root as a writable filesystem inside an A/B slot gets rollback but not integrity — inconsistent with the atomic, never-mutated-in-place philosophy this project already applies at the appliance layer (<code>current</code> is a symlink swap between versioned, immutable release directories; nothing is ever edited in place). A read-only root extends the same discipline down one layer, and gives this DNS appliance a real, ongoing tamper-resistance property beyond just enabling OTA updates.</p><p>This was weighed against the real complexity it adds — primarily that Docker leans heavily on <code>/var/lib/docker</code>, which can&#39;t sensibly live on a read-only filesystem — and concluded the cost is smaller for Sovereign specifically than it would be for a general-purpose Docker host: <code>activate_release</code> already re-imports the Pi-hole image by digest (<code>docker load</code>) on every appliance activation, so Sovereign&#39;s Docker usage is already tolerant of the image cache being ephemeral. A slot switch resetting <code>/var/lib/docker</code> is not a new failure mode this design introduces — it&#39;s a cost the appliance layer already absorbs today.</p><p>Following the reference architecture&#39;s pattern:</p><ul><li><code>/var</code> and <code>/home</code> are reclaimed from each root slot at build time (emptied, replaced with a minimal writable skeleton for services that need <code>PrivateTmp</code>) and bind-mounted from persistent storage at boot, before <code>local-fs.target</code>.</li><li>The systemd journal persists across slot switches (<code>Storage=persistent</code> under a dedicated, bounded-size location), rather than resetting with every base-OS update — losing log history on every update would be a real regression from today.</li><li><code>/etc/machine-id</code> is preserved and synced at boot rather than regenerated per slot, so device identity (and anything keyed off it) survives a base-OS update the same way it already survives an appliance update today.</li></ul><p><strong><code>/opt/sovereign</code> moves out of root entirely, onto <code>/data</code>.</strong> This is not optional once root is read-only — RFC-0014&#39;s appliance-release tree (<code>RELEASES_ROOT</code>, today <code>/opt/sovereign</code>) is actively written to by every appliance update, completely independent of base-OS updates (ADR-0002: &quot;application, appliance, and base-OS versions are tracked independently&quot;). If it stayed inside root, a base-OS update would silently revert appliance content to whatever was baked into that base image at build time, undoing independent appliance progress — a real correctness bug, not just an immutability inconvenience. <code>/data</code> is already this project&#39;s established boundary for &quot;state that must survive independently of the OS&quot; (Pi-hole configuration, device secrets, backup and transaction journals, update state all already live under <code>/data/sovereign</code>); the appliance-release tree belongs there for exactly the same reason, not in a second, newly-invented persistent-storage mechanism.</p><p>Concretely, this is a <strong>bind mount, not a path rename</strong>: <code>/opt/sovereign</code> stays the literal path every already-qualified piece of code, nginx proxy config, and systemd <code>ExecStart=</code> line already hardcodes — none of that gets touched. What changes is what backs it: at boot, before anything needs it, <code>/opt/sovereign</code> gets bind-mounted from real storage under <code>/data</code>, using the exact same &quot;reclaim a path from the read-only root, bind-mount it from persistent storage before <code>local-fs.target</code>&quot; mechanism already being adopted for <code>/var</code> and <code>/home</code> above — this project&#39;s own instance of the reference architecture&#39;s <code>slot-shared</code> pattern, not a separate mechanism invented for this one path.</p><p>What deliberately isn&#39;t adopted from the reference: <code>erofs</code> as the root filesystem type (its own default) or dm-verity-backed integrity verification. Both are real, further hardening steps in the same direction as read-only root, but are separable, additive decisions this RFC doesn&#39;t need to make now — plain read-only ext4 already delivers the property that matters for this milestone (root cannot be mutated in place; a corrupted or tampered root is still detectable by activation&#39;s own signature/health gates, just not by filesystem-level verification on every read). Revisit if a future security-focused RFC wants that stronger guarantee.</p><h3 id="slot-selection-and-health-confirmation-raspberry-pi-tryboot" tabindex="-1">Slot selection and health confirmation: Raspberry Pi <code>tryboot</code> <a class="header-anchor" href="#slot-selection-and-health-confirmation-raspberry-pi-tryboot" aria-label="Permalink to &quot;Slot selection and health confirmation: Raspberry Pi \`tryboot\`&quot;">​</a></h3><p>Recommendation: build directly on the Raspberry Pi 5&#39;s own firmware <code>tryboot_a_b</code> mechanism, following <code>rpi-image-gen</code>&#39;s own official <code>ab_userdata</code> reference example precisely rather than a bespoke approximation, instead of adopting RAUC or Mender. See Alternatives Considered for why.</p><p>The reference example&#39;s <code>autoboot.txt</code> (confirmed directly from its <code>pre-image.sh</code>, which generates it at build time) is short and precise:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[all]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">tryboot_a_b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boot_partition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[tryboot]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">boot_partition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=3</span></span></code></pre></div><p><code>tryboot_a_b=1</code> puts the firmware in a specific, documented A/B mode: a <strong>normal</strong> boot always uses whatever <code>boot_partition</code> the <code>[all]</code> section currently names (partition 2, i.e. boot A, initially). A <strong>trial</strong> boot — triggered from Linux userspace via <code>reboot &quot;0 tryboot&quot;</code>, not by editing this file — uses the <code>[tryboot]</code> section&#39;s <code>boot_partition</code> (3, i.e. boot B) for exactly that one boot.</p><p><strong>Corrected (2026-08-02, hardware-verified — supersedes this paragraph&#39;s original text):</strong> promotion is <em>not</em> automatic. An initial draft of this RFC, written before any hardware testing, claimed the firmware treats an ordinary reboot following a trial boot as implicit confirmation and promotes the trial slot on its own. Direct hardware testing disproves this: from an uncommitted trial boot, a plain <code>sudo reboot</code> reverts to the <em>original</em> slot, not the trial slot. <code>[all]</code> in <code>autoboot.txt</code> only ever changes when something explicitly writes it — <code>rpi-slot-tryboot</code> (from <code>rpi-ab-slot-mapper</code>) prints the promoted config fragment to stdout for exactly this purpose, but nothing invokes it automatically; that is deliberately left to policy in a higher layer, per that layer&#39;s own documentation (&quot;it simply exposes stable by-slot device links leaving policy to higher layers&quot;). This is actually a <em>safer</em> default than the originally-assumed behavior — it means a trial that merely reboots itself, for any reason, reverts automatically rather than committing — but it does mean <code>sovereign-update</code> must perform an explicit commit step, not just an ordinary reboot, to make a trial slot permanent.</p><p>At a high level, applied to Sovereign&#39;s existing transaction model:</p><ol><li>A base-OS update artifact (a new full root-filesystem + boot-partition image pair, signed the same way appliance releases are today) is written to the currently-inactive slot (root B + boot B, in the partition numbers above).</li><li><code>sovereign-update</code> triggers a trial boot: <code>reboot &quot;0 tryboot&quot;</code>. No <code>autoboot.txt</code> edit is needed for this step — the <code>[tryboot]</code> section is already static, always pointing at &quot;the other&quot; boot partition.</li><li>On that trial boot, a systemd unit gated the same way <code>verify-update-health</code> gates appliance activation today — reusing that pattern, not just its name — confirms DNS, HTTP, Console, and Docker health.</li><li>On success, <code>sovereign-update</code> explicitly commits: it runs <code>rpi-slot-tryboot</code> and writes its output over <code>autoboot.txt</code> on the (writable) <code>bootconfig</code> partition, making the trial slot the new <code>[all]</code> default, then performs an ordinary reboot (not another <code>tryboot</code>) into it. The transaction reaches <code>committed</code> in the same <code>sovereign-update status</code> surface appliance updates already report through.</li><li>On failure — health checks fail, or the trial boot never completes at all (crash, hang, power loss) — the device is still running the trial slot&#39;s kernel (if it&#39;s running at all) with <code>[all]</code> in <code>autoboot.txt</code> still pointing at the <em>original</em> slot, since nothing in step 4 ran. Any reboot or power cycle without that explicit commit returns to a normal boot using <code>[all]</code>&#39;s unchanged value — the original slot — automatically. No software fallback logic is required for the crash/hang/power-loss case, and this now includes a hard power cut, hardware-verified directly (see Testing Strategy): a <em>detected</em> health failure (case 3 succeeding at running Sovereign&#39;s own code, but reporting bad health) simply means <code>sovereign-update</code> skips the step-4 commit and reboots or power-cycles back to the known-good slot — the same &quot;do nothing, let it revert&quot; path as any other failure, not a separate rollback mechanism.</li></ol><h3 id="build-on-rpi-image-gen-s-own-a-b-layers-not-a-hand-rolled-equivalent" tabindex="-1">Build on <code>rpi-image-gen</code>&#39;s own A/B layers, not a hand-rolled equivalent <a class="header-anchor" href="#build-on-rpi-image-gen-s-own-a-b-layers-not-a-hand-rolled-equivalent" aria-label="Permalink to &quot;Build on \`rpi-image-gen\`&#39;s own A/B layers, not a hand-rolled equivalent&quot;">​</a></h3><p>Further research (into the <code>ab_userdata</code> example&#39;s own declared layer dependencies) found that its slot-detection and <code>autoboot.txt</code> generation logic isn&#39;t bespoke to that example — it comes from a separate, versioned, documented upstream layer: <strong><code>rpi-ab-slot-mapper</code></strong> (<code>layer/rpi/device/ab-slots.yaml</code> in <code>rpi-image-gen</code>, currently v3.0.0), which itself depends on <code>rpi-storage-binder</code> — a layer this project&#39;s images already require today (<code>image-builder/sovereign/image/sovereign-data/image.yaml</code>&#39;s existing <code>X-Env-Layer-Requires</code>). This substantially changes the implementation plan for the better: build on this layer directly rather than reimplementing equivalent slot-detection logic.</p><p>Concretely, <code>rpi-ab-slot-mapper</code> installs:</p><ul><li>udev rules that create stable <code>/dev/disk/by-slot/active/*</code> and <code>/dev/disk/by-slot/other/*</code> symlinks from GPT partition labels;</li><li><code>rpi-slot-tryboot</code>, which reads those symlinks and prints exactly the <code>autoboot.txt</code> content this RFC&#39;s Proposal section already described (confirmed by reading the script directly — it generates precisely the <code>[all]</code>/<code>tryboot_a_b=1</code>/<code>[tryboot]</code> structure shown above, by resolving the current partition numbers dynamically rather than hardcoding them);</li><li><code>rpi-slot-label</code> / <code>rpi-slot-static</code> for labeling and static-fallback slot identification;</li><li>initramfs-tools/dracut integration for early-boot root selection.</li></ul><p>What it deliberately does <strong>not</strong> do: decide <em>when</em> to write a new <code>autoboot.txt</code>, <em>when</em> to trigger <code>reboot &quot;0 tryboot&quot;</code>, or <em>when</em> to treat a trial boot as confirmed versus roll back. That orchestration — exactly the piece this RFC&#39;s &quot;Reusing RFC-0014&#39;s machinery&quot; section below describes — is left to the consumer, which is precisely where <code>sovereign-update</code>&#39;s own transaction state machine should plug in.</p><p>The full reference layer this piece comes from, <code>image-rota</code> (<code>image/gpt/ab_userdata/image.yaml</code>&#39;s actual layer name), also declares <code>rootfs_type: erofs</code> as its default (not <code>ext4</code>) and pulls in <code>device-base</code>/<code>systemd-min</code> — implementation should confirm exactly which of those are load-bearing for <code>rpi-ab-slot-mapper</code> to function versus specific to that reference example&#39;s own choices (erofs, encryption variants) before assuming the whole dependency chain is required.</p><h3 id="reusing-rfc-0014-s-machinery" tabindex="-1">Reusing RFC-0014&#39;s machinery <a class="header-anchor" href="#reusing-rfc-0014-s-machinery" aria-label="Permalink to &quot;Reusing RFC-0014&#39;s machinery&quot;">​</a></h3><p>The signed-manifest verification, transaction journal, and staged/backing-up/staged/activating/validating/committed state machine <code>sovereign-update</code> already implements should be extended to a new transaction kind (base-OS) rather than duplicated. Concretely:</p><ul><li><code>release-manifest.json</code> already carries <code>components.image_base.version</code> separately from <code>components.appliance.version</code> — this RFC&#39;s artifacts populate that field for real, rather than leaving it static.</li><li>A new artifact role (alongside today&#39;s <code>update_bundle</code>) carries the full root-filesystem image for the inactive slot.</li><li>The existing trust store, key custody (ADR-0006), and rotation (<code>sovereign-update rotate-trust</code>) apply unchanged — this is a new artifact type under the same signing scheme, not a new trust root.</li></ul><h3 id="interaction-with-the-appliance-layer" tabindex="-1">Interaction with the appliance layer <a class="header-anchor" href="#interaction-with-the-appliance-layer" aria-label="Permalink to &quot;Interaction with the appliance layer&quot;">​</a></h3><p>Base-OS updates and appliance updates remain independently versioned and independently triggered, matching today&#39;s manifest structure. An open question (see below) is whether a base-OS update should ever bundle a simultaneous appliance update in the same transaction, or whether they must always be sequential (base-OS commits and reboots cleanly first, <em>then</em> a normal appliance update proceeds against the new slot). The latter is simpler to reason about and is the working assumption for this draft.</p><h2 id="interfaces-and-data-flow" tabindex="-1">Interfaces and Data Flow <a class="header-anchor" href="#interfaces-and-data-flow" aria-label="Permalink to &quot;Interfaces and Data Flow&quot;">​</a></h2><p><strong>Resolved and implemented</strong> (this section originally sketched these as open questions; corrected here now that they&#39;re built, so a reader doesn&#39;t mistake settled, shipped behavior for an unresolved draft):</p><ul><li><code>sovereign-update</code> gained new, dedicated subcommands rather than a <code>--layer</code> flag on the existing appliance verbs — a real reuse of RFC-0014&#39;s <em>machinery</em> (signing, manifest validation, transaction journal, health-gating) but a genuinely separate transaction kind and CLI surface, because a base-OS transaction&#39;s shape doesn&#39;t map cleanly onto the appliance one&#39;s (no backup/restore step; the &quot;slot&quot; concept has no appliance equivalent). The verbs: <code>stage-base-os</code>, <code>trial-base-os</code>, <code>verify-base-os-trial</code> (systemd-invoked health gate, not typically run by hand), <code>commit-base-os</code>, <code>discard-base-os</code>. All in <code>image-builder/sovereign/layer/sovereign-proof.rootfs-overlay/usr/sbin/sovereign-update</code>.</li><li><code>sovereign-update status</code> reports base-OS fields alongside the existing appliance ones, best-effort/absent (not an error) on the plain non-A/B image, which has no slot concept at all: <code>installed_base_os_version</code>, <code>active_slot</code>, <code>base_os_update_state</code>, <code>base_os_target_version</code> (see <code>show_status()</code>). The full base-OS transaction state machine these values move through is <code>staged → trial → validated → committed</code>, with <code>trial_failed</code>/<code>recovery_required</code> → <code>discarded</code> as the failure exits (see <code>BASE_OS_ALLOWED_TRANSITIONS</code>); <code>base_os_update_state</code> is <code>idle</code> when no transaction is in flight.</li></ul><p><strong>Implemented (2026-08-06) — Console UI surfacing for base-OS update state,</strong> the last item this RFC needed:</p><ul><li><em>Backend:</em> <code>image-builder/sovereign/appliance/bin/console-health</code> gained <code>read_base_os_update_status()</code> and a mirrored <code>/api/v1/update/base-os-status</code> route, reading the base-OS <code>base-os-update-status.json</code> (<code>schema_version</code>/<code>state</code>/<code>target_version</code>/<code>updated_at</code>, <code>0o644</code>, world-readable) the same way the existing appliance route already reads <code>update-status.json</code> — no new privacy/security review needed, since the shape and exposure reasoning are identical to the appliance file&#39;s.</li><li><em>Frontend:</em> <code>image-builder/sovereign/appliance/console/assets/console.js</code> gained a base-OS panel alongside the existing appliance <code>renderUpdateDetails()</code>/<code>renderUpdateCheck()</code>/<code>loadUpdateCheck()</code>, showing target version, reboot requirement (base-OS updates always require one, unlike most appliance updates), and last-updated time while a base-OS transaction is staged/trialing/committing.</li><li><em>Scope, as shipped:</em> read-only status <em>display</em> only (mirroring how the appliance panel itself started under ADR-0008, before ADR-0009 later added a Console-triggered <em>install</em> action). A Console-triggered base-OS install (<code>stage-base-os</code>→<code>trial-base-os</code>→<code>commit-base-os</code> from a button, not just SSH) remains a separate, undecided follow-on scope, not bundled into this work.</li><li>Unit-tested (<code>tests/test_console.py</code>, e.g. <code>test_base_os_panel_shows_read_only_transaction_status</code>, <code>test_read_base_os_update_status_reflects_the_transaction_state_file</code>). Built and verified during the same session as the ADR-0010 session-gate hardware qualification pass, which surfaced and fixed a real <code>display:flex</code>/<code>[hidden]</code> CSS specificity bug affecting this panel — see the <a href="./../research/shared-console-session-gate-hardware-qualification-report.html">shared Console session gate hardware qualification report</a>. That report does not itself exercise the base-OS panel end to end against a live base-OS transaction; no dedicated report for that exists yet.</li><li>There is no dedicated Console design brief for this panel — <a href="./../design/console-health.html"><code>docs/design/console-health.md</code></a> predates it and explicitly excludes &quot;update... controls&quot; from its own scope. This RFC and <a href="./../adrs/0009-console-triggered-install.html">ADR-0009</a> are the authoritative specs; don&#39;t look for a separate design doc that doesn&#39;t exist.</li></ul><h2 id="security-and-privacy" tabindex="-1">Security and Privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and Privacy&quot;">​</a></h2><ul><li>No new trust root: base-OS artifacts are signed and verified through the existing <code>sovereign-production-*</code> key custody and channel-scoping already in place (ADR-0006).</li><li>The inactive slot, while being written, is not yet trusted or bootable as a fallback target — <code>tryboot</code>&#39;s one-shot trial-boot semantics mean a partially-written or corrupted slot is never selected for normal boot, only for a single trial that a failed health check (or failure to boot at all) reverts from automatically.</li><li><code>/data</code> remains outside both root slots, so a compromised or corrupted root slot cannot be used to exfiltrate or tamper with persistent secrets by virtue of sharing a filesystem with them — this is already true today and is preserved, not newly introduced, by this design.</li></ul><h2 id="failure-and-recovery" tabindex="-1">Failure and Recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and Recovery&quot;">​</a></h2><ul><li>Trial boot never completes (power loss, kernel panic, hang before Sovereign&#39;s own health-check unit runs): firmware-level <code>tryboot</code> fallback returns to the previous slot with no software dependency at all — the strongest failure mode this design can offer, since it does not depend on anything in the new slot working.</li><li>Trial boot completes but health checks fail: the same <code>verify-update-health</code>-style gate used today reports failure, and the device falls back the same way a failed appliance activation does — needs a concrete decision on whether this triggers an immediate reboot back to the confirmed-good slot or waits for an operator, mirroring the existing appliance rollback design.</li><li>Both slots become unbootable (e.g., a prior failed transaction was never cleaned up before a second one started): needs a documented, qualified worst case, analogous to today&#39;s <code>recovery_required</code> state for appliance transactions, but with real physical-recovery implications. <strong>Resolved and hardware-qualified (2026-08-07/09):</strong> see <a href="./../adrs/0011-external-recovery-image-path.html">ADR-0011</a> — the existing distributable image, reflashed via Raspberry Pi Imager, is the external recovery vehicle (no new recovery-only OS), and the previously-untested &quot;reflash, then restore my data&quot; gap is now closed: the qualification device was genuinely reflashed and a pre-reflash backup restored onto it through the existing, unmodified <code>backup</code>/<code>restore</code> commands, every file independently verified byte-for-byte, with zero code changes needed. See the <a href="./../research/external-recovery-backup-restore-qualification-report.html">external recovery backup/restore qualification report</a>.</li></ul><h2 id="compatibility-and-migration" tabindex="-1">Compatibility and Migration <a class="header-anchor" href="#compatibility-and-migration" aria-label="Permalink to &quot;Compatibility and Migration&quot;">​</a></h2><p>This is the hardest open problem in this proposal and should not be understated: <strong>root itself is small and fixed (2.5G on the qualification device), but <code>data</code> grows via <code>growpart</code> at first boot to consume every byte of physical media left after boot and root — so by the time any device has completed its first boot, there is no unclaimed space left on the disk for a partition that wasn&#39;t already in the build-time layout.</strong> This is true on any device flashed with any image shipped to date, including the device this project&#39;s own hardware qualification runs on — not because root was sized greedily, but because nothing reserves space in advance for a partition the layout didn&#39;t originally define.</p><p>Two consequences follow:</p><ul><li><strong>New images</strong> can adopt the A/B layout directly — this is a build-time layout change with no migration problem.</li><li><strong>Already-flashed devices</strong> cannot gain a second root slot without either (a) an in-place, live repartition-and-shrink of an in-use root filesystem (invasive, high-risk, and likely infeasible to do safely while the filesystem is mounted and serving DNS), or (b) a reflash, which is exactly the operation this whole milestone exists to avoid.</li></ul><p><strong>Decided (2026-08-01, project creator):</strong> the transition to A/B is a one-time reflash for currently-deployed devices, including this project&#39;s own qualification hardware. Every device that goes through that single reflash gains base-OS updates from that point forward with no further reflashing required. Devices are not permanently excluded from this capability based on when they were first flashed; the one-time reflash is the deliberate exception to &quot;no reflashing,&quot; made once, in service of never needing it again for this class of update.</p><h2 id="operations-and-observability" tabindex="-1">Operations and Observability <a class="header-anchor" href="#operations-and-observability" aria-label="Permalink to &quot;Operations and Observability&quot;">​</a></h2><ul><li><code>sovereign-update status</code> must make the active/inactive slot and any in-flight base-OS transaction visible, the same way it already does for appliance transactions.</li><li>Release/build tooling (<code>build-image.yml</code>) needs to produce a base-OS artifact alongside today&#39;s image and appliance-update artifacts, from the same pinned component-version manifest RFC-0014 already requires image and update artifacts to share.</li><li>Storage headroom checks (today&#39;s <code>free_bytes</code> requirement gate) need to account for writing a full second root image, not just an appliance-layer bundle — likely a meaningfully larger number.</li></ul><h2 id="testing-strategy" tabindex="-1">Testing Strategy <a class="header-anchor" href="#testing-strategy" aria-label="Permalink to &quot;Testing Strategy&quot;">​</a></h2><ul><li>Unit tests for manifest/artifact handling follow the same pattern as today&#39;s <code>tests/test_update_*.py</code> — signature verification, size limits, compatibility checks — extended for the new artifact role.</li><li><code>tryboot</code> behavior itself cannot be meaningfully unit-tested; it requires the same real-hardware qualification discipline this project has applied to every other update-system milestone (see the qualification reports linked from RFC-0014 and this milestone&#39;s own history). Expect a real, possibly multi-attempt hardware qualification campaign before this ships, consistent with every prior update-system milestone in this project.</li><li>Forced-failure qualification (interrupted trial boot via a hard power cut, forced health-check failure) is not optional given how central automatic fallback is to this design&#39;s safety case.</li></ul><p><strong>Progress (2026-08-02):</strong> the six-partition GPT layout builds successfully end-to-end (<code>image-builder/sovereign/image/sovereign-ab-data</code>, a new additive layer — the production <code>sovereign-proof.yaml</code> build path is untouched). Verified locally, without a CI round-trip, using native ARM64 Docker on Apple Silicon. Confirmed directly against the built image: GPT partition table with exactly the designed six partitions (<code>bootconfig</code>/<code>boot_a</code>/<code>boot_b</code>/<code>system_a</code>/<code>system_b</code>/<code>data</code>) at the right sizes, <code>autoboot.txt</code> content matching the <code>tryboot_a_b</code> design exactly, and <code>cmdline.txt</code>&#39;s <code>root=</code> correctly using the <code>rpi-ab-slot-mapper</code>-provided by-slot symlink rather than a hardcoded UUID. Not yet done: booting this image at all (real or otherwise), let alone a <code>tryboot</code> trial-boot cycle — that remains the real qualification gate this section describes, unstarted.</p><p><strong>Progress (2026-08-02, continued):</strong> first real boot on the qualification Raspberry Pi 5. Found and fixed, in order: Raspberry Pi Imager&#39;s first-boot account provisioning writing directly to <code>/etc/passwd</code>/<code>/etc/shadow</code>/etc., impossible on read-only root; the new image layer&#39;s bdebstrap hooks missing Docker installation, the ADR-0003 bootstrap account, and almost all appliance service enablement (authored from scratch rather than derived from <code>sovereign-data</code>&#39;s proven hooks); and, most substantively, that individual-file bind mounts for the account database are insufficient on read-only root — <code>passwd</code>/<code>usermod</code>/PAM write account files by renaming a sibling temp file in the <em>same</em> directory, which needs the whole <code>/etc</code> directory writable, not just the mounted file. Fixed by overlaying <code>/etc</code> at boot (<code>sovereign-etc-overlay.service</code>): a writable upper layer on <code>/data</code>, shared across slots (not per-slot) so account state and imager-provisioned configuration survive a future slot switch instead of reverting to build-time defaults, while untouched files still track whatever the current slot&#39;s image ships. Confirmed on hardware: SSH login with the ADR-0003 bootstrap credential, the forced first-login password change, Docker, and the full appliance service set (Pi-hole, Console, nginx) all now work end-to-end on the GPT A/B image. A same-day detour attempted a native-systemd-<code>.mount</code>-unit version of the <code>/etc</code> overlay after a hardware test appeared to hang; the hang turned out to be an unrelated LAN/mDNS reachability issue on the test machine, not a real boot problem, so that redesign was reverted in favor of the already-hardware-proven version. Still not done: an actual <code>tryboot</code> trial-boot cycle, which remains this milestone&#39;s real qualification gate.</p><p><strong>Progress (2026-08-02, tryboot cycle):</strong> the qualification gate itself, qualified. <code>sudo reboot &quot;0 tryboot&quot;</code> correctly performs a one-time trial boot of the inactive slot (verified via a marker file written to the inactive slot&#39;s root beforehand, and via <code>sovereign-slot-var-generator</code>&#39;s own slot detection). Two safety-critical properties confirmed directly, not assumed from documentation:</p><ul><li>An <strong>uncommitted</strong> trial reverts automatically on the very next ordinary (non-tryboot) reboot — no manual intervention, no hard power cycle needed. <code>autoboot.txt</code> is untouched by the trial boot itself (<code>rpi-slot-tryboot</code>, read from <code>rpi-ab-slot-mapper</code>&#39;s own source, is a pure stdout-printing helper with no side effects — &quot;it simply exposes stable by-slot device links leaving policy to higher layers,&quot; per that layer&#39;s own documentation; promotion is not automatic and has no wiring anywhere in the upstream reference either, confirmed by grepping for callers). This is the most important property for the whole design&#39;s safety case, and it held without any Sovereign code written to enforce it — a firmware-level guarantee, not a userspace one.</li><li>An <strong>explicit commit</strong> (<code>rpi-slot-tryboot &gt; /bootfs/autoboot.txt</code>, run manually here since Sovereign hasn&#39;t built the automated health-gated commit step yet) correctly promotes the trial slot to the permanent default, verified to persist through a subsequent ordinary reboot.</li></ul><p>Not yet done: a hard power cut <em>during</em> an active, uncommitted trial (as opposed to a graceful uncommitted reboot, already verified above), and the actual automated <code>sovereign-update</code>-side integration (health gate + commit step) that item 6 on the roadmap still needs — today&#39;s commit step was a manual qualification action, not product code.</p><p><strong>Progress (2026-08-02, forced-failure test):</strong> the hard-power-cut case above, now also qualified. Power was pulled within seconds of issuing <code>sudo reboot &quot;0 tryboot&quot;</code> — before the trial slot could plausibly have finished, likely even started, booting — then restored for a normal cold boot. Result: the device came up cleanly on the committed default (<code>system_b</code>), <code>uptime</code> confirming a genuine fresh boot; <code>autoboot.txt</code> unchanged; no <code>systemd-fsck</code> errors logged. A dry-run <code>e2fsck -fn</code> against the interrupted trial slot&#39;s own root filesystem afterward found zero errors across all five passes — the interruption left no corruption on either slot, not just on the one that ended up booting. Both halves of RFC-0016&#39;s Testing Strategy forced-failure requirement (interrupted trial boot, forced health-check failure) are covered for the interrupted-boot half; forced health-check failure has no product code to test yet (see below).</p><p><strong>Progress (2026-08-03/04, automated integration, full cycle on hardware):</strong> <code>sovereign-update</code> gained real product code for the base-OS transaction flow described in the Proposal section above — <code>stage-base-os</code>, <code>trial-base-os</code>, an automatic health-gate (<code>verify-base-os-trial</code>, invoked by a new boot-time systemd unit, <code>sovereign-verify-base-os-trial.service</code>, gated the same way appliance activation&#39;s <code>verify-update-health</code> is gated) and <code>commit-base-os</code> — reusing the existing Ed25519 signature/trust-store machinery for a new, independently-versioned base-OS manifest (two artifacts: <code>system_boot</code>, <code>system_root</code>). All four commands run against real, signed artifacts and real block devices, with a hard safety check that refuses to ever write to the currently-active slot&#39;s device, verified freshly at write time against the by-slot symlinks rather than any cached/independently-computed slot identity.</p><p>Two real bugs were found and fixed before this reached hardware cleanly:</p><ul><li>A state-machine bug where the generic <code>transition()</code> helper (written for appliance transactions) was reused for base-OS transitions without also overriding <em>where</em> it writes state — silently writing into the appliance&#39;s own <code>transactions/</code> directory and status file instead of <code>base-os-transactions/</code>. Caught by local unit tests before ever touching hardware.</li><li><code>/usr/sbin/reboot</code> on this image is a symlink to <code>systemctl</code>, not a standalone binary. A bare positional <code>&quot;0 tryboot&quot;</code> argument (mimicking traditional <code>reboot ARG</code> syntax) does <strong>not</strong> reliably reach the firmware through it — hardware-verified to silently fall back to an ordinary reboot instead, even though the exact same argument form had worked in earlier manual qualification testing via an interactive shell. <code>systemctl</code>&#39;s own documented <code>--reboot-argument=ARG</code> option (&quot;Specify argument string to pass to reboot()&quot;) is required instead, and was confirmed on hardware to trigger a real trial boot reliably. This was <strong>only</strong> caught by hardware testing — every local test stub is a fake <code>reboot</code>/<code>systemctl</code> script that simply logs its argv, which can&#39;t distinguish real firmware-reaching behavior from a plain reboot that happens to also succeed and return exit code 0.</li></ul><p>With both fixed, a complete, unattended (aside from the manual CLI invocations standing in for a future &quot;install this update&quot; trigger) cycle succeeded on the qualification device: <code>stage-base-os</code> verified and wrote a signed artifact pair to the inactive slot; <code>trial-base-os</code> triggered a real trial boot; the boot-time health gate ran automatically and reported <code>validated</code> against real Docker/DNS/Console health (not a stub); <code>commit-base-os</code> wrote the promoted <code>autoboot.txt</code> and rebooted; the device came up on the newly-committed slot as the permanent default, confirmed via a genuine fresh <code>uptime</code> and <code>autoboot.txt</code>&#39;s <code>[all]</code> section now pointing at the promoted partition.</p><p>This required first resolving an unrelated, real finding: the qualification device&#39;s <code>eth0</code> DHCP client had stopped acquiring an IPv4 lease (a driver/systemd-networkd race, <code>ENOMEDIUM</code> despite a stable carrier — see <a href="./../research/eth0-dhcp-carrier-race-finding.html"><code>docs/research/eth0-dhcp-carrier-race-finding.md</code></a>), which was silently failing the appliance health check (no internet → Pi-hole&#39;s <code>gravity.db</code> never builds) independent of anything in this milestone&#39;s own code. Worked around with a persistent static IP on the qualification device; the general DHCP-client bug remains open and unrelated to RFC-0016.</p><p>RFC-0016&#39;s core acceptance criteria — a working <code>tryboot</code> A/B cycle with signed artifacts, health-gating, and both graceful and forced-failure recovery — are now met and hardware-verified. Remaining before this is production-ready: Console UI surfacing for base-OS update state.</p><p><strong>Progress (2026-08-04, release tooling):</strong> <code>scripts/create-base-os-release.py</code> now exists, mirroring <code>create-update-release.py</code>&#39;s own shape and conventions (unsigned manifest + artifacts out; signing stays a separate, explicit step via the existing <code>sign-update-manifest.py</code>, per ADR-0006&#39;s key-custody boundary). It takes already-built raw <code>boot.vfat</code>/<code>root.ext4</code> images as input rather than building them itself — the same relationship <code>create-update-release.py</code> has to a pre-built Pi-hole OCI archive — since genimage&#39;s own deploy step produces android-sparse-format output, not the plain raw images <code>stage-base-os</code> writes sequentially onto a block device.</p><p>This surfaced a real gap in the <code>stage-base-os</code> implementation itself, fixed alongside the release tooling: it had only ever been exercised against uncompressed qualification artifacts, but real release artifacts need zstd compression to be practical (a 3G raw root image compresses to a fraction of that) — <code>write_raw_artifact</code> now decompresses while streaming directly onto the device rather than assuming the artifact is already raw. <code>BASE_OS_BOOT_MEDIA_TYPE</code>/<code>BASE_OS_ROOT_MEDIA_TYPE</code> gained an explicit <code>+zstd</code> suffix to say so, matching the existing <code>update_bundle</code> artifact&#39;s own <code>+tar+zstd</code> convention. Not yet wired into <code>.github/workflows/build-image.yml</code> at this point: doing so needs the image-build pipeline itself to export the raw boot/root images somewhere accessible before genimage&#39;s sparse conversion, which the <code>deploy/</code> output alone doesn&#39;t do — see the next entry below.</p><p><strong>Progress (2026-08-05, recover/prune integration):</strong> <code>recover</code>/<code>prune</code> now cover base-OS transactions, closing the gap noted above. This needed more care than the appliance-transaction case it mirrors, because of a boot-ordering fact: <code>sovereign-update-recovery.service</code> runs early (<code>Before=sovereign-pihole.service</code>), while the trial health-gate (<code>sovereign-verify-base-os-trial.service</code>) runs later (<code>After=...sovereign-console.service, nginx.service</code>). That means recovery runs on <em>every</em> boot, including a genuinely in-progress trial boot, before the health-gate has had a chance to run — a naive sweep of <code>trial</code>-state transactions would misfire and recover a trial that hasn&#39;t failed at all. Fixed by recording which slot a trial transaction targets (<code>target_slot</code>, via a new <code>slot_label_for()</code> helper) at stage time, and comparing it against the currently active slot at recovery time: still on the target slot means the trial is genuinely in progress (leave it alone), already reverted means the transaction was abandoned (mark <code>recovery_required</code>). Added <code>discard-base-os</code> to close out terminal-state transactions, and extended <code>prune</code>&#39;s sweep and post-prune <code>sync_directory</code> calls to include the <code>base-os-transactions</code> directory alongside the existing appliance one.</p><p>This also surfaced and fixed a real, pre-existing bug: <code>current_slot_label()</code> parsed the by-slot symlink&#39;s <code>readlink</code> target for a <code>system_a</code>/<code>system_b</code> suffix, but that target is just a raw device node path (e.g. <code>../../mmcblk0p4</code>) and never contains the slot label at all — <code>sovereign-update status</code> had been silently reporting <code>&quot;active_slot&quot;: &quot;mmcblk0p4&quot;</code> instead of a proper slot name since this was first written. The new recovery logic was the first consumer that actually needed a <em>correct</em> slot label to compare against, rather than one that was purely informational. Fixed by shelling out to <code>blkid -s PARTLABEL -o value</code>, matching the existing <code>sovereign-slot-var-generator</code> script&#39;s own approach.</p><p><strong>Progress (2026-08-05, CI wiring):</strong> <code>.github/workflows/build-image.yml</code> can now produce an unsigned base-OS update candidate end to end, closing the gap left by the release-tooling entry above. This turned out to need more than a packaging step: CI&#39;s existing &quot;Build image&quot; run only ever targets <code>sovereign-proof.yaml</code>, the plain non-A/B config, and that image&#39;s <code>boot.vfat</code>/<code>root.ext4</code> are structurally the wrong shape for a base-OS update (no tryboot partitions to stage onto). Producing a base-OS candidate genuinely requires a second, separate image build against <code>sovereign-ab-proof.yaml</code> — so it&#39;s gated behind a new opt-in <code>build_base_os_candidate</code> dispatch input (default <code>false</code>, mirroring <code>build_update_candidate</code>&#39;s own shape) rather than doubling every build&#39;s runtime unconditionally.</p><p>Getting at the raw <code>boot.vfat</code>/<code>root.ext4</code> at all needed a small <code>scripts/build-sovereign-image.sh</code> change: <code>rpi-image-gen</code>&#39;s own deploy step (<code>layer/base/deploy.sh</code> in the vendored tool) only ever exports <code>*.sparse</code> files out of its work directory, even though genimage builds the plain raw images too, as an intermediate step, on the way to its android-sparse conversion. <code>build-sovereign-image.sh</code> now <code>docker cp</code>s those two raw files out of the container directly (into <code>evidence/base-os/</code>, alongside the script&#39;s existing oci/bootstrap/ sovereign-release evidence exports) — a tolerated no-op for configs, like the plain image, that were never meant to feed a base-OS release. The workflow&#39;s new &quot;Build base-OS image&quot; / &quot;Package unsigned base-OS update candidate&quot; / &quot;Upload base-OS update artifact&quot; steps mirror the existing appliance-update-candidate ones exactly, including the same ADR-0006 unsigned-manifest caveat in the draft-release step (CI never holds the signing key; an operator still signs offline before publishing).</p><p><strong>Progress (2026-08-05, CI wiring live-verified):</strong> the CI wiring above had only been proven against Docker-stubbed tests until now — actually dispatching the workflow (<code>build_base_os_candidate: true</code>, no draft release) against real Docker/<code>rpi-image-gen</code> was the natural next check, and it passed cleanly: both the primary and second (A/B) image builds succeeded, run <a href="https://github.com/sovereignfs/sovereign-os/actions/runs/31030670477" target="_blank" rel="noreferrer">31030670477</a>, 7m49s total. The uploaded <code>sovereign-base-os-0.1.0-preview.24-rpi5-arm64</code> artifact was downloaded and checked directly rather than just trusting a green run: both <code>boot.img.zst</code>/<code>root.img.zst</code> files&#39; recomputed SHA-256 matched <code>base-os-manifest.json</code>&#39;s declared digests exactly, and the manifest validated cleanly against <code>sovereign-update</code>&#39;s own <code>validate_base_os_manifest()</code> — the same validator <code>stage-base-os</code> runs on a device.</p><p>This confirms the CI pipeline itself is correct end to end. It does not confirm the pipeline&#39;s <em>output</em> against real hardware — every hardware tryboot/trial/commit/recovery cycle qualified so far in this RFC used manually-built images, never an artifact that came out of this workflow. That&#39;s the natural next verification once there&#39;s a reason to cut a real base-OS release, not attempted here.</p><p><strong>Progress (2026-08-06, second base-OS update without a reflash — last Acceptance Criteria item closed):</strong> exactly the verification the entry above named as the natural next step, done for real. Dispatched a fresh CI build (<code>0.1.0-preview.25</code>, <code>base_os_key_id: sovereign-production-1</code>, source <code>4cae39f</code>) since the earlier <code>0.1.0-preview.24</code> artifact was signed for the wrong key ID and could never verify against the device&#39;s actual trust store; the device operator signed the resulting manifest offline with the real production key per ADR-0006. Staging it against the qualification device — already on the A/B layout since its 2026-08-02 reflash — surfaced two real already-flashed-device compatibility gaps in sequence (a pre-<code>ffe2278</code> binary rejecting the modern <code>+zstd</code> manifest format outright, then a <code>DOWNGRADE_REJECTED</code> from <code>&quot;proof&quot;</code> sorting after <code>&quot;preview&quot;</code> under semver prerelease comparison), and a third once a trial boot was actually triggered (the recovery auditor false-flagging a healthy trial as interrupted, because the transaction — staged by that same pre-fix binary — was missing a <code>target_slot</code> field the current recovery logic depends on). Each was root-caused against the actual source (diffing old vs. new <code>sovereign-update</code> behavior directly, not guessed at), worked around for qualification purposes without touching the device&#39;s read-only root, and the underlying <code>tryboot</code>/health-gate/commit cycle itself worked cleanly once past them: staged → trial → validated → committed, confirmed persistent across a subsequent ordinary reboot. A fourth finding — <code>installed_base_os_version</code> never changing because <code>/etc/sovereign-base-os-release</code>&#39;s <code>VERSION</code> is a hardcoded, unparameterized build-time placeholder — was caught by the same pass but isn&#39;t itself a blocker to the Acceptance Criteria item, since <code>base_os_update_state</code>/<code>base_os_target_version</code> (the fields <code>status</code> and Console actually key off) were correct throughout. Full account, including exact commands, transaction IDs, and root-cause diffs, in the <a href="./../research/second-base-os-update-hardware-qualification-report.html">second base-OS update qualification report</a>. This closes the last item in this RFC&#39;s own Acceptance Criteria; see that section for the updated checklist and what&#39;s still open (fixes for the four findings above).</p><p><strong>Progress (2026-08-06, Console base-OS panel live-hardware exercise — also closed):</strong> same-day follow-on to the entry above. The live Console (<code>sovereign-console.service</code>, serving from <code>/opt/sovereign/releases/0.1.0-dev/appliance/</code>) turned out to be stale too — same root cause as the pass above, a different binary (<code>bin/console-health</code>) — so it had neither the <code>/api/v1/update/base-os-status</code> backend route nor the frontend panel. Deployed the current-<code>main</code> versions of <code>console-health</code>, <code>console.js</code>, <code>console.css</code>, and <code>index.html</code>, plus a targeted patch adding just the new nginx <code>location = /api/v1/update/base-os-status</code> block (not a wholesale <code>nginx.conf</code> replace, since that file also carries the unrelated ADR-0010 session-gate change already tested and reverted off this device in its own qualification pass — out of scope here). Verified via <code>curl</code> against the real nginx proxy: the served <code>index.html</code>/<code>console.js</code>/<code>console.css</code> are byte-identical to what was deployed, the base-OS panel markup is present in the served HTML, and the endpoint genuinely returns this device&#39;s real committed transaction through the real proxy — which <code>console.js</code>&#39;s <code>renderBaseOsStatus()</code> correctly maps to &quot;Base-OS update installed.&quot; with the target version and update time populated. Full account appended to the same <a href="./../research/second-base-os-update-hardware-qualification-report.html">qualification report</a>. Every RFC-0016 Acceptance Criteria item is now met.</p><p><strong>Progress (2026-08-07, real fixes for the four qualification findings):</strong> <code>compare_versions</code> gained an explicit <code>PRERELEASE_CHANNEL_ORDER = (&quot;proof&quot;, &quot;preview&quot;, &quot;rc&quot;, &quot;stable&quot;)</code> table so a known leading prerelease identifier is ranked by this project&#39;s actual release chronology instead of plain lexical comparison (which put <code>&quot;proof&quot;</code> after <code>&quot;preview&quot;</code>, backwards) — an unrecognized channel word still falls back to the original lexical behavior. Six new tests in <code>tests/test_update_version_compare.py</code> cover it, including that same-channel numeric comparison and release-core dominance are unaffected. Separately, <code>pre-image.sh</code> now templates <code>/etc/sovereign-base-os-release</code> from <code>$SOVEREIGN_VERSION</code>/<code>$SOVEREIGN_CHANNEL</code> (already validated and exported as Docker <code>ENV</code> vars before this hook runs) instead of a hardcoded <code>&quot;0.1.0-proof.1&quot;</code> literal, mirroring how <code>image-builder/build-sovereign-image</code> already templates the appliance&#39;s own <code>/etc/sovereign-release</code> — <code>tests/test_ab_data_image.py</code> now asserts the template is used and the old literal is gone. The other two findings from the qualification report needed no code change: both were fixed in <code>main</code> already, the qualification device simply hadn&#39;t received the fix yet. Full test suite (230 tests) passes.</p><p><strong>Progress (2026-08-08/09, external recovery-image path hardware qualification):</strong> <a href="./../adrs/0011-external-recovery-image-path.html">ADR-0011</a>&#39;s decision, hardware-qualified for real, closing the last item this RFC&#39;s Failure and Recovery and Unresolved Questions sections had left open. Produced a real &quot;verified&quot; appliance transaction (the device&#39;s <code>0.1.0-dev</code> installed version fell outside every real release&#39;s compatible bounds, so a custom signed candidate was built with <code>update_source_minimum=0.1.0-dev</code>), took a real backup, copied it off-device, then genuinely reflashed the qualification device — requiring a new CI artifact for the actual flashable A/B disk image, since the workflow previously only ever extracted partition images for base-OS candidates and never uploaded the assembled image itself (<code>Upload flashable A/B image artifact</code>, gated the same way as the rest of the base-OS-candidate path). Copied the backup back onto the fresh device and ran <code>restore --force</code> (the version mismatch a genuine reflash produces). Every persisted file — Pi-hole&#39;s full state (<code>gravity.db</code>, <code>pihole.toml</code>, TLS certs, custom DNS entries, etc.) and the admin-password secret — was independently verified byte-for-byte against the original off-device backup, not just trusted from the tool&#39;s own reported status, and the restored device&#39;s actual DNS service was confirmed genuinely working, not just files matching. <strong>Zero code changes to <code>backup</code>/<code>restore</code> were needed</strong> — ADR-0011&#39;s central claim, that their validation is purely content-based with no device-identity binding, held up under real destructive conditions exactly as designed. Full account in the <a href="./../research/external-recovery-backup-restore-qualification-report.html">external recovery backup/restore qualification report</a>.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives Considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives Considered&quot;">​</a></h2><h3 id="rauc-or-mender-adopt-a-third-party-a-b-ota-framework" tabindex="-1">RAUC or Mender (adopt a third-party A/B OTA framework) <a class="header-anchor" href="#rauc-or-mender-adopt-a-third-party-a-b-ota-framework" aria-label="Permalink to &quot;RAUC or Mender (adopt a third-party A/B OTA framework)&quot;">​</a></h3><p>Both are established, and both support Raspberry Pi via <code>tryboot</code> integration under the hood — meaning even adopting one of them still ultimately delegates to the same firmware mechanism this RFC proposes using directly. What they add on top is primarily: multi-hardware-target abstraction (irrelevant — this project targets exactly one board), bundle/manifest formats and signing of their own (redundant with the signed-manifest, trust-rotation, and staged/health-gated/rollback system this project already built and hardware-qualified for the appliance layer), and in Mender&#39;s case, an optional hosted management service (explicitly the kind of dependency this project&#39;s governance rejects — see the image-build assessment&#39;s rejection of Raspberry Pi Connect on the same grounds). Adopting either would mean running two parallel signing/trust/state-machine systems — one already built and proven (RFC-0014), one imported — for conceptually the same problem at two layers of the same device. Rejected as unnecessary complexity and a real governance mismatch, not because either is technically unsound.</p><h3 id="ostree-style-atomic-filesystem-trees" tabindex="-1">OSTree-style atomic filesystem trees <a class="header-anchor" href="#ostree-style-atomic-filesystem-trees" aria-label="Permalink to &quot;OSTree-style atomic filesystem trees&quot;">​</a></h3><p>A single filesystem with atomically-swapped checkouts (as used by Fedora Silverblue and similar) instead of two full physical partitions. More storage-efficient (shared, deduplicated content between &quot;slots&quot;), but it is a much larger integration effort — it changes the whole filesystem management model, is not natively supported by <code>rpi-image-gen</code>, and has no precedent anywhere else in this project&#39;s tooling. Rejected for this milestone as disproportionate engineering cost relative to a project with a single maintainer and a single hardware target; worth reconsidering only if physical A/B&#39;s storage cost (a full second root partition) proves genuinely prohibitive on real hardware.</p><h3 id="defer-indefinitely-keep-documenting-the-gap" tabindex="-1">Defer indefinitely, keep documenting the gap <a class="header-anchor" href="#defer-indefinitely-keep-documenting-the-gap" aria-label="Permalink to &quot;Defer indefinitely, keep documenting the gap&quot;">​</a></h3><p>Rejected: the ADR-0009 qualification incident this session already demonstrated the cost is not hypothetical, and the cost compounds with every future rootfs-level change this project ships.</p><h2 id="drawbacks-and-maintenance-cost" tabindex="-1">Drawbacks and Maintenance Cost <a class="header-anchor" href="#drawbacks-and-maintenance-cost" aria-label="Permalink to &quot;Drawbacks and Maintenance Cost&quot;">​</a></h2><ul><li>A second root partition roughly doubles the storage this project&#39;s base OS occupies on every device, on top of whatever the base-OS artifact itself costs in transfer/build time.</li><li><code>tryboot</code>&#39;s exact configuration surface (which firmware versions support which <code>autoboot.txt</code> syntax) needs to be confirmed against the actual EEPROM version this project&#39;s images ship, not assumed from general Raspberry Pi documentation. The firmware version requirement itself is already satisfied on this project&#39;s qualification hardware (see Proposal); what remains unverified is the exact config syntax, not whether the feature exists.</li><li>The <strong>boot partition must grow</strong> — confirmed directly on real hardware, not estimated: today&#39;s 98M boot partition has only 49M free, and a second slot&#39;s kernel + initramfs alone (~24M) would consume essentially all of that margin. This is a required image-layout change this RFC depends on, not an optional optimization.</li><li>This is a genuinely bigger, riskier surface than any prior update- system milestone: a failure mode here can leave a device unable to boot at all, not just unable to reach <code>committed</code> state. The qualification bar (see Testing Strategy) needs to reflect that.</li><li>Read-only root adds real new surface beyond the partition/tryboot mechanism itself: <code>/var</code>/<code>/home</code> reclaim-and-bind-mount at boot, journal persistence configuration, machine-id sync, and moving <code>/opt/sovereign</code> onto <code>/data</code> all need their own correctness verification, not just &quot;the OS boots.&quot; A subtly wrong bind-mount ordering (before <code>local-fs.target</code>, before anything that writes to <code>/var</code> starts) is a real, easy-to-get-wrong failure mode this design introduces that a writable-root approach wouldn&#39;t have had.</li><li>Docker&#39;s storage under <code>/var/lib/docker</code> is not preserved across a slot switch under this design (see &quot;Root is read-only&quot;). Acceptable because <code>activate_release</code> already re-imports the Pi-hole image by digest on every appliance activation, but this should be explicitly qualified, not just assumed — confirm Docker itself starts cleanly against an empty <code>/var/lib/docker</code> after a slot switch, not only that the subsequent <code>docker load</code> succeeds.</li></ul><h2 id="unresolved-questions" tabindex="-1">Unresolved Questions <a class="header-anchor" href="#unresolved-questions" aria-label="Permalink to &quot;Unresolved Questions&quot;">​</a></h2><ul><li><strong>Resolved: move to GPT.</strong> Not because <code>tryboot_a_b</code> is confirmed to require it at the firmware level (that remains unverified either way) — but because the six-partition layout itself doesn&#39;t fit MBR&#39;s practical ceiling of 4 primary partitions (or 3 primary + 1 extended containing logical partitions). <code>rpi-image-gen</code>&#39;s reference example uses GPT&#39;s own partition-table format directly, cleanly addressing 6 partitions with <code>in-partition-table = true</code> entries; reproducing the same layout under MBR would mean nesting most of the new partitions inside an extended partition, working against the tooling instead of with it, for a hardware target that has no need to preserve MBR specifically. Today&#39;s images move to GPT as part of this milestone.</li><li><strong>Resolved: use the <code>/dev/disk/by-slot/active/*</code> symlink scheme verbatim</strong> — it comes from <code>rpi-ab-slot-mapper</code>, a separate, versioned upstream layer (not something to reimplement), and Sovereign already depends on that layer&#39;s own prerequisite (<code>rpi-storage-binder</code>). Still open: whether the small <code>bootconfig</code> partition specifically is required by that layer or is incidental to the <code>ab_userdata</code> example, and which of <code>image-rota</code>&#39;s other declared dependencies (<code>device-base</code>, <code>systemd-min</code>) are load-bearing versus specific to that example&#39;s own choices (erofs, encryption variants Sovereign doesn&#39;t need).</li><li>CLI/API shape for triggering and observing a base-OS transaction — new subcommands vs. extending existing ones.</li><li>Whether a base-OS update and an appliance update can ever be part of the same transaction, or must always be sequential.</li><li>Sizing for root A/root B: fixed at build time from today&#39;s package list, or does the image-build layout need a configurable margin for future growth?</li><li><strong>Resolved and hardware-qualified (2026-08-07/09):</strong> what &quot;external recovery-image path&quot; (named as a goal in ROADMAP item 6) actually looks like — see <a href="./../adrs/0011-external-recovery-image-path.html">ADR-0011</a> and Failure and Recovery above.</li></ul><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li>A device on a new A/B-layout image can receive a signed base-OS update, boot the new slot on trial, pass health checks, and commit — hardware-qualified on Raspberry Pi 5, following this project&#39;s established qualification discipline.</li><li>A forced trial-boot failure (health check failure, and separately, a hard power cut mid-trial-boot) is qualified to correctly fall back to the previous slot with no data loss and no manual recovery needed.</li><li><code>/data</code> survives a base-OS update, a rollback, and a repeated cycle of both, unaffected — including <code>/opt/sovereign</code>&#39;s appliance-release tree, now living there: an appliance update installed <em>after</em> a base-OS update must still be present and correctly <code>current</code> after a <em>subsequent</em> base-OS update, proving the two layers are genuinely independent, not just independently versioned on paper.</li><li>Root is confirmed read-only at runtime (a write attempt fails), with <code>/var</code> and <code>/home</code> correctly bind-mounted and writable, Docker starting cleanly against a slot-switch-reset <code>/var/lib/docker</code>, the journal and <code>/etc/machine-id</code> surviving a base-OS update unchanged.</li><li><code>sovereign-update status</code> and Console correctly represent an in-flight and a committed base-OS transaction. <strong>Fully met:</strong> <code>status</code>&#39;s <code>base_os_update_state</code>/<code>base_os_target_version</code> fields are hardware-confirmed correct through a real stage/trial/commit cycle, and the Console base-OS panel — deployed onto the (separately stale) live Console — was confirmed serving that same real transaction data through the real nginx proxy, both the served files and the API response verified directly. See the <a href="./../research/second-base-os-update-hardware-qualification-report.html">second base-OS update qualification report</a>. That same pass found <code>installed_base_os_version</code> was a hardcoded build-time placeholder that never reflected the real installed version (Finding 4 in that report); fixed 2026-08-07 by templating <code>pre-image.sh</code>&#39;s <code>/etc/sovereign-base-os-release</code> from <code>$SOVEREIGN_VERSION</code>, the same mechanism the appliance layer&#39;s own version stamping already uses.</li><li><strong>Met (2026-08-06):</strong> the qualification device — already migrated via the decided one-time reflash on 2026-08-02 — received a second base-OS update without a second reflash: staged, trialed, health-gated, and committed, with the commit confirmed persistent across a subsequent ordinary reboot. See the <a href="./../research/second-base-os-update-hardware-qualification-report.html">second base-OS update qualification report</a> for the full account, including four real defects the pass surfaced (a pre-fix binary rejecting modern manifests, a <code>proof</code>/<code>preview</code> semver-ordering collision, a stale-binary transaction missing the <code>target_slot</code> field that made recovery falsely flag a healthy trial as interrupted, and the <code>installed_base_os_version</code> placeholder above). Only &quot;any other currently-deployed device&quot; beyond this one remains unverified, and this project has exactly one qualification device.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>Accepted (2026-08-01, project creator).</strong> Direction approved as written: A/B root on Raspberry Pi&#39;s native <code>tryboot</code>, reusing RFC-0014&#39;s signed/staged/health-gated/rollback machinery rather than adopting a third-party OTA framework. The migration question is resolved (see Compatibility and Migration): a one-time reflash for currently-deployed devices, A/B thereafter. Remaining items in Unresolved Questions are implementation-detail decisions, not open direction questions, and may be resolved during implementation and hardware qualification rather than blocking the start of that work.</p>`,106)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
